describe('Login Form Validation', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
  });

  it('should display error messages when both username and password fields are empty', () => {
    // Attempt to submit the login form with empty fields
    cy.get('[data-test="login-button"]').click();

    // Verify the error container is visible
    cy.get('[data-test="error"]').should('be.visible');

    // Verify the error message for username is displayed
    cy.get('[data-test="error"]').should('contain', 'Username is required');

    // Verify the error message for password is displayed
    cy.get('[data-test="error"]').should('contain', 'Password is required');

    // Verify the login button is still enabled
    cy.get('[data-test="login-button"]').should('not.be.disabled');
  });

  it('should display error message when only password field is empty', () => {
    // Enter username only
    cy.get('[data-test="user-input"]').type('standard_user');

    // Attempt to submit the login form
    cy.get('[data-test="login-button"]').click();

    // Verify the error container is visible
    cy.get('[data-test="error"]').should('be.visible');

    // Verify the error message for password is displayed
    cy.get('[data-test="error"]').should('contain', 'Password is required');

    // Verify the error message for username is NOT displayed
    cy.get('[data-test="error"]').should('not.contain', 'Username is required');

    // Verify the login button is still enabled
    cy.get('[data-test="login-button"]').should('not.be.disabled');
  });
});
